import {ROUTES,TABS,readFilters,selectShots,selectedSummary,asCsv,modelProbability} from './analytics-core.js';
import {escapeHtml as esc} from './ui-kit.js';
const $=s=>document.querySelector(s),names={overview:'Overview',chances:'Chance creation',model:'Model check',method:'Data & method'},modelNames={constant:'Constant conversion rate',distance:'Distance only',full:'Touchline model xG'},state=readFilters(location.search);let data,model,validation,provenance,rows=[],page=0,selected=null,loadNumber=0;
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}):'—',pct=n=>Number.isFinite(n)?fmt(n*100,1)+'%':'—',ci=v=>v?`${fmt(v[0],3)}–${fmt(v[1],3)}`:'Insufficient sample';
const metric=(label,value,note)=>`<div class="metric"><small>${label}</small><strong>${value}</strong><small>${note}</small></div>`;
function saveUrl(){history.replaceState(null,'','?'+new URLSearchParams(state));}
async function fetchJson(file){const r=await fetch('./analytics-data/'+file+'.json');if(!r.ok)throw Error('The research files could not be loaded. Try again when connected.');return r.json();}
async function load(){const number=++loadNumber;$('#status').textContent='Loading the research dataset…';$('#dashboard').hidden=true;try{const result=await Promise.all([fetchJson(state.competition),model?Promise.resolve(model):fetchJson('model'),validation?Promise.resolve(validation):fetchJson('validation'),provenance?Promise.resolve(provenance):fetchJson('provenance')]);if(number!==loadNumber)return;[data,model,validation,provenance]=result;if(!data.summaries[state.team])state.team='all';$('#competition').value=state.competition;$('#team').innerHTML='<option value="all">All teams</option>'+data.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#team').value=state.team;$('#route').innerHTML=Object.entries(ROUTES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('#route').value=state.route;$('#dashboard').hidden=false;render();}catch(e){$('#status').innerHTML=`<span class="error">${esc(e.message)}</span> <button id="retry">Retry loading</button>`;}}
function summaryCards(s){return `<div class="metrics">${metric('Observed shots',fmt(s.shots,0),`${s.shotMatches} matches with shots`)}${metric('Observed goals',fmt(s.goals,0),'From included Shot events')}${metric('Touchline model xG',fmt(s.xg),'Sum of estimated goal probabilities')}${metric('xG per team-match',fmt(s.xgPerTeamMatch),`${s.teamMatches} team-matches, including zero-shot games`)}</div>`;}
function bars(){const summaries=data.summaries[state.team];return Object.entries(ROUTES).filter(([k])=>k!=='all').map(([k,label])=>{const s=summaries[k];return `<div class="route-bar"><header><b>${label}</b><span>${fmt(s.xgPerShot,3)} xG / shot</span></header><div class="track"><span style="width:${Math.min(100,(s.xgPerShot||0)*250)}%"></span></div><small>${s.shots} shots · ${s.shotMatches} matches · ${fmt(s.xgPerTeamMatch)} xG / team-match<br>95% interval, xG/shot: ${ci(s.intervals?.xgPerShot)}${s.sufficient?'':' · descriptive only'}</small></div>`;}).join('');}
function overview(){const s=selectedSummary(data,state);return `<span class="eyebrow">THE QUESTION</span><h2>Which routes create better shooting opportunities?</h2><p>Shot volume and shot quality answer different questions. Compare how frequently chances occur with their estimated goal probability, then inspect the underlying attempts.</p>${summaryCards(s)}<div class="grid"><section class="card"><h2>Opportunity quality</h2><p class="small">Current team selection · route comparisons use all four routes. Intervals resample whole matches.</p>${bars()}</section><section class="card"><h2>What repeats across datasets?</h2><p class="small">All teams, irrespective of filters. Fixed comparisons: each route against all other routes. These are exploratory patterns, not causal effects or significance tests.</p>${validation.findings.map(f=>{const a=f.datasets.england,b=f.datasets['world-cup'];return `<div class="route-bar"><b>${ROUTES[f.route]}</b><p>${f.intervalDirectionRepeats?'The difference has the same direction in both datasets, with both intervals on that side of zero.':f.sameDirection?'Point estimates share a direction, but uncertainty does not support a clear repeated difference.':'The direction does not repeat, or sample support is insufficient.'}</p><small>England difference: ${fmt(a.difference,3)} xG/shot<br>World Cup difference: ${fmt(b.difference,3)} xG/shot<br>95% difference intervals: England ${ci(a.differenceInterval)}; World Cup ${ci(b.differenceInterval)}.<br>Conditional on this fitted model; training uncertainty is not included.</small></div>`;}).join('')}</section></div><div class="note"><b>How to use this:</b> identify a route worth reviewing, open Chance creation, and inspect its shot locations and source matches. A higher average does not mean a team should simply use that route more often; opponent, game state and execution also differ.</div><p><b>Expected goals (xG)</b> is an estimated probability that a shot becomes a goal. A 0.10 estimate means roughly one goal per ten comparable attempts under this model, not that this particular shot will score.</p>`;}
function shotMap(){return `<svg class="chart shot-map" viewBox="-3 -3 111 74" role="img" aria-labelledby="pitch-title pitch-desc"><title id="pitch-title">Shot locations for the selected filters</title><desc id="pitch-desc">${rows.length} shots, attacking left to right. Gold marks goals; green marks other outcomes. The paginated shot table provides equivalent inspect controls.</desc><rect x="0" y="0" width="105" height="68" fill="#143a31" stroke="#91b0a2" stroke-width=".2"/><path d="M52.5 0V68 M0 13.84H16.5V54.16H0 M105 13.84H88.5V54.16H105 M0 24.84H5.5V43.16H0 M105 24.84H99.5V43.16H105" fill="none" stroke="#91b0a2" stroke-width=".2"/><circle cx="52.5" cy="34" r="9.15" fill="none" stroke="#91b0a2" stroke-width=".2"/>${rows.map(r=>`<circle class="shot-dot${selected===r.id?' selected':''}" data-shot="${r.id}" cx="${r.x*1.05}" cy="${r.y*.68}" r="${.25+Math.sqrt(r.xg)*1.2}" fill="${r.goal?'#f5cb76':'#baff63'}"><title>${r.period} ${Math.floor(r.second/60)}′ · ${fmt(r.xg,3)} model xG · ${r.goal?'Goal':'No goal'}</title></circle>`).join('')}</svg>`;}
function detail(){const s=rows.find(r=>r.id===selected);if(!s)return '<p class="small">Select a dot or use Inspect in the table to see an attempt.</p>';const m=data.matches.find(m=>m.id===s.match),team=data.teams.find(t=>t.id===s.team);return `<div class="detail" role="status"><b>${esc(team?.name)} · ${esc(m?.label)}</b><p>${s.period} · ${fmt(s.second/60,1)} period minutes · ${s.goal?'Observed goal':'Observed non-goal'}</p><p>${ROUTES[s.route]} · ${fmt(s.distance,1)} m · ${esc(s.body.replace('_','/'))} · <b>${fmt(modelProbability(s,model),3)} Touchline model xG</b></p><small>Event ${s.id} · Match ${s.match} · <a href="./analytics-data/matches/${s.match}.json">Source match metadata</a>. Period time restarts in the second half; this is not full-match minute.</small></div>`;}
function chances(){const s=selectedSummary(data,state),slice=rows.slice(page*50,page*50+50);return `${summaryCards(s)}<div class="grid"><section class="card"><h2>The shot map</h2><div class="legend"><span><i></i>Non-goal</span><span><i class="goal"></i>Goal</span><span>Size = Touchline model xG</span></div>${shotMap()}${detail()}</section><section class="card"><h2>Compare preceding-pass routes</h2>${bars()}<p class="small">Cross has priority over through ball. No linked pass can include carries, rebounds, missing links or passes outside the ten-second window. It does not mean an unassisted attempt.</p></section></div><section class="card" style="margin-top:20px"><h2>Inspect the evidence</h2><div class="actions"><button id="download">Download filtered shots CSV</button><span class="small">${rows.length} included attempts · observed outcomes and model estimates are separate columns.</span></div><div class="table-wrap"><table><caption>Shots matching the filters · ${slice.length?`${page*50+1}–${page*50+slice.length}`:'0'} of ${rows.length}</caption><thead><tr><th>Inspect</th><th>Source match</th><th>Team</th><th>Period / minute</th><th>Route</th><th>Observed outcome</th><th>Touchline model xG</th></tr></thead><tbody>${slice.map(r=>{const m=data.matches.find(m=>m.id===r.match);return `<tr><td><button data-inspect="${r.id}">Inspect ${r.id}</button></td><td><a href="./analytics-data/matches/${r.match}.json" title="Match ID ${r.match}">${esc(m?.label||r.match)}</a><br><small>ID ${r.match}</small></td><td>${esc(data.teams.find(t=>t.id===r.team)?.name)}</td><td>${r.period} / ${fmt(r.second/60,1)}</td><td>${ROUTES[r.route]}</td><td>${r.goal?'Goal':'No goal'}</td><td>${fmt(r.xg,3)}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><button id="previous" class="secondary" ${page===0?'disabled':''}>Previous 50</button><span>Page ${page+1} of ${Math.max(1,Math.ceil(rows.length/50))}</span><button id="next" class="secondary" ${(page+1)*50>=rows.length?'disabled':''}>Next 50</button></div></section>`;}
function calibration(bins){return `<svg class="chart calibration" viewBox="0 0 440 350" role="img" aria-labelledby="cal-title"><title id="cal-title">Calibration: estimated versus observed goal frequency. Dashed line represents perfect calibration; use the table for numeric values.</title><path d="M55 25V295H410 M55 295L410 25" fill="none" stroke="#819a9d" stroke-dasharray="5 5"/>${[0,.2,.4,.6,.8,1].map(v=>`<text x="${55+v*355}" y="315" fill="#b6c7ca" text-anchor="middle" font-size="12">${v}</text><text x="45" y="${299-v*270}" fill="#b6c7ca" text-anchor="end" font-size="12">${v}</text>`).join('')}${bins.filter(b=>b.n).map(b=>`<circle cx="${55+b.predicted*355}" cy="${295-b.observed*270}" r="${4+Math.min(9,Math.sqrt(b.n)/10)}" fill="#baff63"/>`).join('')}<text x="230" y="342" fill="#b6c7ca" text-anchor="middle" font-size="13">Estimated goal probability →</text><text x="15" y="170" fill="#b6c7ca" transform="rotate(-90 15 170)" text-anchor="middle" font-size="13">Observed goal frequency →</text></svg>`;}
function modelCheck(){const report=validation.evaluation[state.competition],full=report.models.full,constant=report.models.constant,distance=report.models.distance;return `<span class="eyebrow">FROZEN MODEL / UNSEEN MATCHES</span><h2>Does the model generalize?</h2><p>This report covers the <b>entire ${esc(data.label)} evaluation dataset</b>, independent of the team and route filters. No match here was used for training or tuning.</p><div class="metrics">${metric('Evaluation shots',fmt(report.shots,0),`${report.goals} observed goals`)}${metric('Full-model log loss',fmt(full.metrics.logLoss,4),'Lower is better')}${metric('Full-model Brier score',fmt(full.metrics.brier,4),'Lower is better')}${metric('Full-model ROC AUC',fmt(full.metrics.auc,3),'Ranking quality; higher is better')}</div><div class="note">${full.metrics.logLoss<constant.metrics.logLoss?'The full model has lower point-estimate log loss than the constant baseline.':'The full model does not improve point-estimate log loss over the constant baseline.'} ${full.metrics.logLoss<distance.metrics.logLoss?'It also improves the distance-only point estimate.':'It does not improve the distance-only point estimate.'} These comparisons are not a guarantee of future performance.</div><section class="card"><h2>Compare against simple baselines</h2><p>Log loss penalizes confident mistakes. Brier score measures squared probability error. ROC AUC measures ranking, not calibration. Intervals resample whole matches 2,000 times.</p><div class="table-wrap"><table><caption>Held-out ${esc(data.label)} · each cell shows value [95% interval]</caption><thead><tr><th>Model</th><th>Log loss ↓</th><th>Brier ↓</th><th>ROC AUC ↑</th></tr></thead><tbody>${Object.entries(report.models).map(([k,v])=>`<tr><th>${modelNames[k]}</th>${['logLoss','brier','auc'].map(m=>`<td>${fmt(v.metrics[m],4)} [${ci(v.intervals[m])}]</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="grid" style="margin-top:20px"><section class="card"><h2>Do probabilities match frequencies?</h2>${calibration(full.calibration)}<div class="table-wrap"><table><caption>Five fixed bins for the full model; empty bins show no estimate.</caption><thead><tr><th>Bin</th><th>Shots</th><th>Mean estimate</th><th>Observed frequency [95% interval]</th></tr></thead><tbody>${full.calibration.map(b=>`<tr><td>${fmt(b.low,1)}–${fmt(b.high,1)}</td><td>${b.n}</td><td>${pct(b.predicted)}</td><td>${pct(b.observed)} [${b.intervals?.observed?b.intervals.observed.map(pct).join('–'):'—'}]</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Small model, inspectable assumptions</h2><p>The full logistic model uses distance, shooting angle and body part. Wyscout combines head and body into one category; it cannot isolate headers reliably.</p><p>Training: ${model.training.matches} matches and ${fmt(model.training.shots,0)} shots from France, Germany, Italy and Spain, 2017–18. Five match-grouped development folds choose regularization by log loss. Every fold fits its own preprocessing.</p><p>Regularization C: full ${model.models.full.C}; distance-only ${model.models.distance.C}. Constant baseline: ${pct(model.constant)} development conversion.</p><p>Outcome tags, shot destination, assist tags, player identity and pass route are excluded from prediction inputs.</p><a href="./analytics-data/model.json" download>Download coefficients and development-fold audit</a></section></div>`;}
function method(){return `<h2>Real data. Reproducible analysis.</h2><div class="note">These are historical observations and estimated shot probabilities. They do not validate Touchline’s game simulation or prove that a tactical change causes more goals.</div><div class="grid"><section class="card"><h2>Coverage and exclusions</h2><div class="table-wrap"><table><caption>Included regular-time Shot events; other scoring events are outside the model target.</caption><thead><tr><th>Competition</th><th>Matches</th><th>Shots</th><th>Goals</th></tr></thead><tbody>${Object.entries(provenance.coverage).map(([k,v])=>`<tr><th>${esc(k.replace('_',' '))}</th><td>${v.matches}</td><td>${v.includedShots}</td><td>${v.includedGoals}</td></tr>`).join('')}</tbody></table></div><p>England and World Cup are held out. Euro 2016 is not used. Penalties and direct free kicks are separate event types and excluded; extra time, shootouts and own goals outside Shot events are excluded. Totals therefore differ from match scores.</p><details><summary>Every exclusion count</summary><pre>${esc(JSON.stringify(provenance.exclusions,null,2))}</pre></details><p>Invalid or missing shot coordinates are rejected. Unknown or ambiguous body-part tags remain an explicit unknown category.</p></section><section class="card"><h2>Method, in plain language</h2><ol class="method-list"><li>Map 0–100 shot coordinates to an assumed 105 × 68 metre pitch, attacking left to right.</li><li>Associate the nearest accurate same-team pass within ten seconds, stopping at any opponent event, new period or stoppage. This is not a verified assist.</li><li>Train logistic regression on four leagues; select C from 0.01, 0.1, 1 and 10 using development-only folds, seed 42.</li><li>Freeze the model, then evaluate England and the World Cup separately. Historical league differences may reduce transferability.</li><li>Resample whole matches 2,000 times for percentile intervals. Comparisons need at least 30 shots from five matches. Sparse samples remain descriptive.</li><li>Per-team-match exposure includes games with zero shots in that route. No individual causal or scouting recommendation is claimed.</li></ol></section></div><section class="card" style="margin-top:20px"><h2>Sources and downloads</h2><p>${esc(provenance.attribution)} <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0 license</a>. We extract, classify and model shots; the resulting estimates are Touchline’s, not Wyscout’s.</p>${Object.values(provenance.sources).map(s=>`<p class="small"><a href="${esc(s.url)}">${esc(s.title)}</a> · version ${s.version} · ${s.bytes.toLocaleString()} bytes<br>SHA-256: <code>${s.sha256}</code></p>`).join('')}<div class="actions"><a href="./analytics-data/england.csv" download>England shots CSV</a><a href="./analytics-data/world-cup.csv" download>World Cup shots CSV</a><a href="./analytics-data/provenance.json" download>Provenance and exclusion audit</a><a href="./analytics-data/validation.json" download>Evaluation and findings JSON</a></div><h3>Reproduce from source</h3><pre>python -m pip install -r scripts/analytics/requirements.txt\npython scripts/analytics/build.py</pre><p>The public repository includes the pipeline and tests. Raw source downloads are cached locally; versioned derived data, coefficients and reports are served as static files. No prediction API, login or live AI service is required.</p><p><a href="https://github.com/aaravjj2/touchline/tree/main/scripts/analytics">Open analysis source</a></p></section>`;}
function render(){page=Math.min(page,Math.max(0,Math.ceil(selectShots(data,state).length/50)-1));rows=selectShots(data,state);saveUrl();$('#tabs').innerHTML=TABS.map(t=>`<button role="tab" id="tab-${t}" aria-controls="content" aria-selected="${state.tab===t}" tabindex="${state.tab===t?0:-1}" data-tab="${t}">${names[t]}</button>`).join('');$('#content').setAttribute('aria-labelledby','tab-'+state.tab);$('#content').innerHTML=({overview,chances,model:modelCheck,method}[state.tab])();$('#status').textContent=`${data.label} · ${state.team==='all'?'All teams':data.teams.find(t=>String(t.id)===state.team)?.name} · ${rows.length.toLocaleString()} matching shots. Historical observations; separate from game saves.`;}
$('#competition').addEventListener('change',e=>{state.competition=e.target.value;state.team='all';page=0;selected=null;load();});for(const key of ['team','route'])$('#'+key).addEventListener('change',e=>{state[key]=e.target.value;page=0;selected=null;render();});
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();$('#tab-'+state.tab).focus();}const shot=e.target.closest('[data-shot],[data-inspect]');if(shot){selected=Number(shot.dataset.shot||shot.dataset.inspect);render();$('.detail')?.scrollIntoView({block:'nearest'});}if(e.target.id==='next'||e.target.id==='previous'){page+=e.target.id==='next'?1:-1;render();$('#'+e.target.id)?.focus();}if(e.target.id==='download'){const blob=new Blob([asCsv(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`touchline-${state.competition}-${state.team}-${state.route}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(e.target.id==='copy-link'){try{await navigator.clipboard.writeText(location.href);$('#status').textContent='Analysis link copied.';}catch{$('#status').textContent='Copy this page’s address to share the selected analysis.';}}if(e.target.id==='retry')load();});
$('#tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=TABS.indexOf(e.target.closest('[data-tab]')?.dataset.tab||state.tab);state.tab=e.key==='Home'?TABS[0]:e.key==='End'?TABS.at(-1):TABS[(i+(e.key==='ArrowRight'?1:3))%4];render();$('#tab-'+state.tab).focus();});
load();
